// Pink Alert live demo: drag a sample scan into the analysis station.
// Results come from window.PINK_DEMO (assets/demo/results.js), generated by the published models.
(() => {
  const data = window.PINK_DEMO;
  const app = document.getElementById('demo-app');
  if (!app || !Array.isArray(data)) return;

  const CLASSES = ['Benign', 'Normal', 'Malignant'];
  const ALERT = {
    1: { cls: 'lvl-ok', label: 'All clear', body: 'Nothing stands out in this scan. Keep scanning regularly and save the result for comparison.' },
    0: { cls: 'lvl-watch', label: 'Worth a check', body: 'The analyzer found a region that is most likely benign. Only a clinician can confirm this, so book a routine check-up.' },
    2: { cls: 'lvl-act', label: 'See a doctor', body: 'This scan shares features with malignant tissue. It is not a diagnosis, but it is a strong reason to seek a professional exam promptly.' },
  };
  const MODELS = [['rf', 'Random Forest', 60], ['mlp', 'MLP', 25], ['svm', 'SVM', 15]];

  const thumbs = document.getElementById('thumbs');
  const zone = document.getElementById('dropzone');
  const result = document.getElementById('result');
  const $ = (id) => document.getElementById(id);
  const seen = new Map();
  let timer = null;

  data.forEach((d) => {
    const b = document.createElement('button');
    b.type = 'button';
    b.className = 'thumb';
    b.draggable = true;
    b.dataset.id = d.id;
    b.setAttribute('role', 'listitem');
    b.setAttribute('aria-label', `Analyze scan ${d.id}`);
    b.innerHTML = `<img src="${d.img}" alt="" loading="lazy" draggable="false"><span class="id">${d.id}</span>`;
    b.addEventListener('dragstart', (e) => { e.dataTransfer.setData('text/plain', d.id); e.dataTransfer.effectAllowed = 'copy'; });
    b.addEventListener('click', () => analyze(d.id, true));
    thumbs.appendChild(b);
  });

  // Desktop drag-and-drop
  zone.addEventListener('dragover', (e) => { e.preventDefault(); e.dataTransfer.dropEffect = 'copy'; zone.classList.add('over'); });
  zone.addEventListener('dragleave', () => zone.classList.remove('over'));
  zone.addEventListener('drop', (e) => {
    e.preventDefault(); zone.classList.remove('over');
    const id = e.dataTransfer.getData('text/plain');
    if (id) analyze(id, false);
  });

  // Touch drag (phones don't fire HTML5 drag events)
  let ghost = null, touchId = null;
  thumbs.addEventListener('touchstart', (e) => {
    const t = e.target.closest('.thumb'); if (!t) return;
    touchId = t.dataset.id;
  }, { passive: true });
  thumbs.addEventListener('touchmove', (e) => {
    if (!touchId) return;
    const p = e.touches[0];
    if (!ghost) {
      ghost = document.createElement('img');
      ghost.src = data.find((d) => d.id === touchId).img;
      ghost.style.cssText = 'position:fixed;width:72px;height:72px;object-fit:cover;border-radius:4px;border:1px solid #fff;pointer-events:none;z-index:99;opacity:.9';
      document.body.appendChild(ghost);
    }
    ghost.style.left = p.clientX - 36 + 'px'; ghost.style.top = p.clientY - 36 + 'px';
    const r = zone.getBoundingClientRect();
    zone.classList.toggle('over', p.clientX > r.left && p.clientX < r.right && p.clientY > r.top && p.clientY < r.bottom);
    e.preventDefault();
  }, { passive: false });
  thumbs.addEventListener('touchend', () => {
    if (ghost) {
      const hit = zone.classList.contains('over');
      ghost.remove(); ghost = null; zone.classList.remove('over');
      if (hit) analyze(touchId, false);
    }
    touchId = null;
  });

  // "Show tumor": dotted outline of the expert-annotated lesion (from the dataset's mask)
  function addTumorToggle(d) {
    const btn = document.createElement('button');
    btn.type = 'button'; btn.className = 'tumor-btn'; btn.setAttribute('aria-pressed', 'false');
    btn.textContent = 'Show tumor';
    btn.addEventListener('click', () => {
      const on = btn.getAttribute('aria-pressed') !== 'true';
      btn.setAttribute('aria-pressed', String(on)); btn.textContent = on ? 'Hide tumor' : 'Show tumor';
      zone.querySelectorAll('.tumor-svg, .tumor-note').forEach((n) => n.remove());
      if (on) drawTumor(d);
    });
    zone.appendChild(btn);
  }
  function drawTumor(d) {
    const img = zone.querySelector('img'); if (!img) return;
    const zw = zone.clientWidth, zh = zone.clientHeight;
    const a = d.aspect || (img.naturalWidth / img.naturalHeight);
    let w = zw, h = zw / a; if (h > zh) { h = zh; w = zh * a; }
    const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
    svg.setAttribute('class', 'tumor-svg'); svg.setAttribute('viewBox', '0 0 1000 1000'); svg.setAttribute('preserveAspectRatio', 'none');
    Object.assign(svg.style, { left: (zw - w) / 2 + 'px', top: (zh - h) / 2 + 'px', width: w + 'px', height: h + 'px' });
    svg.innerHTML = d.tumor.map((poly) => `<path d="M${poly.map(([x, y]) => `${(x * 1000).toFixed(1)} ${(y * 1000).toFixed(1)}`).join(' L')} Z"/>`).join('');
    zone.appendChild(svg);
    const note = document.createElement('span'); note.className = 'tumor-note'; note.textContent = 'Outline from the dataset\'s expert annotation';
    zone.appendChild(note);
  }
  new ResizeObserver(() => {
    const btn = zone.querySelector('.tumor-btn[aria-pressed="true"]');
    if (!btn) return;
    const id = zone.querySelector('.stamp')?.textContent.match(/SCAN (\d+)/)?.[1];
    zone.querySelectorAll('.tumor-svg, .tumor-note').forEach((n) => n.remove());
    const d = data.find((x) => x.id === id); if (d) drawTumor(d);
  }).observe(zone);

  function pct(v) { return (v * 100).toFixed(1) + '%'; }

  function analyze(id, fromClick, count = true) {
    const d = data.find((x) => x.id === id); if (!d) return;
    clearTimeout(timer);
    thumbs.querySelectorAll('.thumb').forEach((t) => t.setAttribute('aria-pressed', String(t.dataset.id === id)));

    zone.querySelectorAll('img, .stamp, .tumor-btn, .tumor-svg, .tumor-note').forEach((n) => n.remove());
    zone.querySelector('.empty').hidden = true;
    const img = document.createElement('img'); img.src = d.img; img.alt = `Ultrasound scan ${d.id}`;
    const stamp = document.createElement('span'); stamp.className = 'stamp'; stamp.textContent = `SCAN ${d.id} · ANALYZING`;
    zone.prepend(img); zone.appendChild(stamp);
    zone.classList.remove('scanning');
    if (count) { void zone.offsetWidth; zone.classList.add('scanning'); }
    result.hidden = true;
    if (fromClick && window.matchMedia('(max-width: 960px)').matches) zone.scrollIntoView({ behavior: 'smooth', block: 'center' });

    timer = setTimeout(() => {
      stamp.textContent = `SCAN ${d.id} · COMPLETE`;
      if (d.tumor && d.tumor.length) addTumorToggle(d);
      const a = ALERT[d.pred];
      $('r-title').textContent = CLASSES[d.pred];
      const pill = $('r-pill'); pill.className = 'pill ' + a.cls; pill.textContent = a.label;
      $('r-body').textContent = a.body;

      const order = [0, 1, 2].sort((x, y) => d.ensemble[y] - d.ensemble[x]);
      $('r-probs').innerHTML = order.map((k, i) =>
        `<div class="prob${i === 0 ? ' top' : ''}"><span>${CLASSES[k]}</span><div class="track"><i></i></div><b>${pct(d.ensemble[k])}</b></div>`).join('');
      requestAnimationFrame(() => requestAnimationFrame(() => {
        $('r-probs').querySelectorAll('.track i').forEach((bar, i) => { bar.style.width = d.ensemble[order[i]] * 100 + '%'; });
      }));

      $('r-models').innerHTML = MODELS.map(([k, name, w]) => {
        const p = d.models[k]; const top = p.indexOf(Math.max(...p));
        return `<tr><td>${name} (${w}%)</td>${p.map((v, i) => `<td class="${i === top ? 'hi' : ''}">${pct(v)}</td>`).join('')}</tr>`;
      }).join('') + `<tr><td><b>Ensemble</b></td>${d.ensemble.map((v, i) => `<td class="${i === d.pred ? 'hi' : ''}"><b>${pct(v)}</b></td>`).join('')}</tr>`;

      const ok = d.pred === d.truth;
      const v = $('r-verdict'); v.className = 'verdict ' + (ok ? 'right' : 'wrong');
      v.innerHTML = ok
        ? `<b>Matches the expert label.</b> This image is labelled ${CLASSES[d.truth].toLowerCase()} in the dataset.`
        : `<b>Missed.</b> This image is labelled ${CLASSES[d.truth].toLowerCase()} in the dataset, but the ensemble predicted ${CLASSES[d.pred].toLowerCase()}. Errors like this are why Pink Alert always routes users to a clinician.`;
      result.hidden = false;

      if (!count) return;
      seen.set(id, ok);
      const t = thumbs.querySelector(`[data-id="${id}"]`);
      t.classList.add('done', ok ? 'right' : 'wrong');
      $('t-done').textContent = seen.size;
      $('t-right').textContent = [...seen.values()].filter(Boolean).length;
    }, count ? 1100 : 0);
  }

  $('t-reset').addEventListener('click', () => {
    clearTimeout(timer); seen.clear();
    thumbs.querySelectorAll('.thumb').forEach((t) => { t.className = 'thumb'; t.setAttribute('aria-pressed', 'false'); });
    zone.querySelectorAll('img, .stamp, .tumor-btn, .tumor-svg, .tumor-note').forEach((n) => n.remove());
    zone.querySelector('.empty').hidden = false; zone.classList.remove('scanning');
    result.hidden = true; $('t-done').textContent = '0'; $('t-right').textContent = '0';
  });
})();
